"use client"

import { useEffect, useRef } from "react"

export default function AnimatedPhone() {
  const phoneRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const phone = phoneRef.current
    if (!phone) return

    const keyframes = `
      @keyframes float {
        0%, 100% { transform: translateY(0px) rotateZ(-1deg); }
        50% { transform: translateY(-20px) rotateZ(1deg); }
      }
    `
    const style = document.createElement("style")
    style.textContent = keyframes
    document.head.appendChild(style)
    phone.style.animation = "float 6s ease-in-out infinite"

    return () => style.remove()
  }, [])

  return (
    <div className="relative  md:h-full  flex items-center justify-center">
      <div className="absolute inset-0 bg-gradient-to-t from-primary/10 to-transparent rounded-3xl" />

      {/* Animated glow effect */}
      <div className="absolute inset-0 opacity-30">
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-gradient-to-r from-primary/20 to-accent/20 rounded-full blur-3xl animate-pulse" />
      </div>

      <div ref={phoneRef} className="relative w-full h-full max-w-sm">
        {/* Phone Frame */}
         {/* Animated content */}
            <div className="flex-1 w-full p-6 flex flex-col items-center justify-center gap-4 overflow-hidden">
              <img src="/Screenshot_2026-01-02_015142-removebg-preview.png" alt="" />
            </div>
      </div>
    </div>
  )
}
